#!/usr/bin/env bun
/**
 * First platform admin (bootstrap only; afterwards use the hub's grid).
 *
 *   FIREBASE_PROJECT_ID=<project> bun run seed-admin you@example.com
 *
 * Needs gcloud application-default credentials with Firestore access to the
 * `platform` database. Writes users/<email> with platformAdmin true and an
 * audit entry. Does not grant any POC.
 */
import { appDb } from "@lsv-poc/poc-auth/firebase";

const email = process.argv[2]?.toLowerCase().trim();
if (!email || !email.includes("@") || !process.env.FIREBASE_PROJECT_ID) {
  console.error("usage: FIREBASE_PROJECT_ID=<project> bun run seed-admin <email>");
  process.exit(1);
}
const db = appDb("platform");
const at = new Date().toISOString();
await db.collection("users").doc(email).set({ email, platformAdmin: true, pocs: {}, updatedAt: at, updatedBy: "seed-admin" }, { merge: true });
await db.collection("audit").add({ at, actor: "seed-admin", action: "platform_admin_seeded", email, pocId: "", before: null, after: null });
console.log(`users/${email} is a platform admin`);
