#!/usr/bin/env bun
/**
 * Register a POC in the hub registry (platform database pocs/<id>), so the
 * hub may grant it. Run only after the POC is live and probed.
 *
 *   FIREBASE_PROJECT_ID=<project> bun run skills/poc-deploy/tools/register-poc.ts <app-repo-dir> [--repo owner/name]
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { appDb } from "../../../packages/poc-auth/src/firebase";

const dir = process.argv[2];
const i = process.argv.indexOf("--repo");
if (!dir || !process.env.FIREBASE_PROJECT_ID) {
  console.error("usage: FIREBASE_PROJECT_ID=<project> register-poc.ts <app-repo-dir> [--repo owner/name]");
  process.exit(1);
}
const m = JSON.parse(readFileSync(join(dir, "poc.json"), "utf8"));
const record = { id: m.id, name: m.name, hostname: m.hostname, description: m.description, dataSensitivity: m.dataSensitivity, dataModel: m.dataModel, repo: i > 0 ? process.argv[i + 1] : "", registeredAt: new Date().toISOString() };
const db = appDb("platform");
await db.collection("pocs").doc(m.id).set(record, { merge: true });
await db.collection("audit").add({ at: record.registeredAt, actor: "poc-deploy", action: "poc_registered", email: "", pocId: m.id, before: null, after: null });
console.log(`registered pocs/${m.id}`);
