  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `  [${detail}]` : ""}`);
};

async function idTokenFor(email: string) {
  const u = await auth.getUserByEmail(email).catch(() => null);
  if (!u) throw new Error(`${email} has no account; grant or create it in the hub first`);
  const ct = await auth.createCustomToken(u.uid);
  const r = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signInWithCustomToken?key=${apiKey}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Referer: `${APP_URL}/` },
    body: JSON.stringify({ token: ct, returnSecureToken: true }),
  });
  const b = (await r.json()) as { idToken?: string };
  if (!b.idToken) throw new Error("custom token exchange failed");
  return b.idToken;
}
const session = (idToken: string) => fetch(`${APP_URL}/api/auth/session`, { method: "POST", headers: { "Content-Type": "application/json", Origin: APP_URL }, body: JSON.stringify({ idToken }) });

console.log(`# Signed out: ${APP_URL}`);
for (const p of ["/", "/index.html", "/admin"]) {
  const r = await fetch(`${APP_URL}${p}`, { redirect: "manual" });
  check(`GET ${p} -> 303 to /sign-in`, r.status === 303 && (r.headers.get("location") ?? "").endsWith("/sign-in"), String(r.status));
}
check("GET /api/health -> 200", (await fetch(`${APP_URL}/api/health`)).status === 200);
check("GET /api/admin/settings -> 401", (await fetch(`${APP_URL}/api/admin/settings`)).status === 401);

console.log(`\n# Unallocated: ${outsider}`);
const o = await session(await idTokenFor(outsider));
check("POST /api/auth/session -> 403 and no cookie", o.status === 403 && !o.headers.get("set-cookie"), String(o.status));

console.log(`\n# Allocated: ${member}`);
const s = await session(await idTokenFor(member));
