cd ~/Documents/workspace/projects/lsv-poc-platform/code && cat >> terraform/platform/variables.tf <<'EOF'

variable "browser_key_id" {
  description = "Id of the Firebase auto-created browser API key (gcloud services api-keys list). Empty leaves the key unmanaged. Import before the first apply: terraform import 'google_apikeys_key.browser[0]' projects/<project>/locations/global/keys/<id>"
  type        = string
  default     = ""
}
EOF
cat >> terraform/platform/main.tf <<'EOF'

# The Firebase web API key is public by design (it ships in every page), so
# what it may be used for is what protects it: only from the POC hostnames and
# the sign-in handler, and only against the sign-in services plus Firestore
# (for a POC registered as client-access). Firebase creates the key
# unrestricted; it is imported here rather than created.
resource "google_apikeys_key" "browser" {
  count        = var.browser_key_id == "" ? 0 : 1
  project      = var.project_id
  name         = var.browser_key_id
  display_name = "Browser key (auto created by Firebase)"

  restrictions {
    browser_key_restrictions {
      allowed_referrers = [
        "${var.poc_domain}/*",
        "*.${var.poc_domain}/*",
        "${var.project_id}.firebaseapp.com/*",
      ]
    }
    api_targets { service = "identitytoolkit.googleapis.com" }
    api_targets { service = "securetoken.googleapis.com" }
    api_targets { service = "firestore.googleapis.com" }
  }

  lifecycle { prevent_destroy = true }
}
EOF
