"use client";

import { useCallback, useEffect, useState } from "react";

type Grid = { pocs: { id: string; name: string }[]; users: { email: string; platformAdmin: boolean; pocs: Record<string, string> }[] };
type Cell = "" | "member" | "admin";

/** Users by POCs. Each cell is none, member or admin; changing it grants or revokes at once. Platform admins only. */
export default function Admin() {
  const [grid, setGrid] = useState<Grid | null>(null);
  const [status, setStatus] = useState("");
  const [newEmail, setNewEmail] = useState("");

  const load = useCallback(async () => {
    const r = await fetch("/api/admin/allocations");
    if (r.status === 401) return window.location.assign("/sign-in");
    if (r.status === 403) return setStatus("Platform admins only.");
    setGrid(await r.json());
  }, []);
  useEffect(() => {
    load();
  }, [load]);

  async function change(email: string, pocId: string, value: Cell) {
    setStatus(`Saving ${email} / ${pocId}…`);
    const r = await fetch("/api/admin/allocations", {
      method: value ? "POST" : "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, pocId, role: value || undefined }),
    });
  return (
    <main className="page">
      <h1>Allocate access</h1>
      <p className="muted">
        <a href="/">Back</a> · Changes take effect on the person&apos;s next request. Every change is audited.
      </p>
      <p>
        <label>
          Add a person <input type="email" placeholder="name@example.com" value={newEmail} onChange={(e) => setNewEmail(e.target.value.trim())} />
        </label>
      </p>
      <div className="grid-wrap">
        <table>
          <thead>
            <tr>
              <th>Person</th>
              {grid.pocs.map((p) => (
                <th key={p.id} title={p.name}>
                  {p.id}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {users.map((u) => (
              <tr key={u.email}>
                <td>
                  {u.email}
                  {u.platformAdmin && <span className="muted"> (platform admin)</span>}
                </td>
                {grid.pocs.map((p) => (
                  <td key={p.id}>
                    <select aria-label={`${u.email} ${p.id}`} value={(u.pocs[p.id] as Cell) ?? ""} onChange={(e) => change(u.email, p.id, e.target.value as Cell)}>
                      <option value="">none</option>
                      <option value="member">member</option>
                      <option value="admin">admin</option>
                    </select>
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p aria-live="polite">{status}</p>
    </main>
  );
}
