  /** Write the allocation and audit atomically, then derive claim and override from it. */
  async function allocate(actor: string, email: string, pocId: string, role: AppRole | null): Promise<Response> {
    const at = new Date(now() * 1000).toISOString();
    const existing = await d.auth.getUserByEmail(email);
    if (!existing && !role) return json(404, { error: "No such user" });
    // Email only, no password: the sign-in pool is email link.
    const uid = existing?.uid ?? (await d.auth.createUser(email)).uid;
    const claims = existing?.customClaims ?? {};

    let before: AppRole | null;
    try {
      before = await d.store.applyAllocation({ email, pocId, role, uid, actor, at });
    } catch (err) {
      d.log.error("allocation write failed", { err, email, pocId });
      return json(500, { error: "Could not record the change; nothing was applied" });
    }

    try {
      await d.auth.setCustomUserClaims(uid, withAppClaim(claims, pocId, role));
      if (!role) await d.auth.revokeRefreshTokens(uid);
      await d.store.writeAccessOverride(pocId, uid, { role, updatedAt: now() * 1000, email });
    } catch (err) {
      await d.store.appendAudit({ at, actor, action: "claims_sync_failed", email, pocId, before, after: role, detail: String(err) }).catch(() => {});
      d.log.error("claim or override sync failed", { err, email, pocId, event: "hub.sync_failed" });
      return json(502, { error: "Recorded, but the sign-in claim did not update. Retry, or run the resync script." });
    }
    d.log.info(role ? "granted" : "revoked", { event: role ? "hub.grant" : "hub.revoke", actor, email, pocId, before, after: role });
    return json(200, { email, pocId, before, after: role });
  }

  return {
    async launcher(request: Request) {
      const c = await caller(request);
      if (c instanceof Response) return c;
      const registry = new Map((await d.store.listPocs()).map((p) => [p.id, p]));
      const pocs = Object.entries(c.user.pocs)
        .filter(([id]) => registry.has(id))
        .map(([id, role]) => ({ id, name: registry.get(id)!.name, url: `https://${id}.${pocDomain}`, role }))
        .sort((a, b) => a.name.localeCompare(b.name));
    async grant(request: Request) {
      const c = await platformAdmin(request, true);
      if (c instanceof Response) return c;
      const a = await parseAllocation(request, true);
      if (!a) return json(400, { error: "email, pocId and role (member or admin) required" });
      // ISC-38: only registered POCs can be granted.
      if (!(await d.store.getPoc(a.pocId))) return json(404, { error: `POC ${a.pocId} is not in the registry` });
      return allocate(c.user.email, a.email, a.pocId, a.role);
    },

    async revoke(request: Request) {
      const c = await platformAdmin(request, true);
      if (c instanceof Response) return c;
      const a = await parseAllocation(request, false);
      if (!a) return json(400, { error: "email and pocId required" });
      // Revoking does not require the POC to still be registered: removing access must always be possible.
      return allocate(c.user.email, a.email, a.pocId, null);
    },
  };
