"use client";

import { useCallback, useEffect, useState } from "react";

type Poc = { id: string; name: string; hostname: string; description: string; status: "live" | "pending" };
type Grid = { pocs: Poc[]; users: { email: string; platformAdmin: boolean; pocs: Record<string, string> }[] };
type Cell = "" | "member" | "admin";

const LABEL: Record<Cell, string> = { "": "No access", member: "Member", admin: "Admin" };

/** People by POCs. Each cell says what that person can do in that POC; changing it grants or revokes at once. Hub administrators only. */
export default function Admin() {
  const [grid, setGrid] = useState<Grid | null>(null);
  const [status, setStatus] = useState("");
  const [newEmail, setNewEmail] = useState("");

  const load = useCallback(async () => {
    const r = await fetch("/api/admin/allocations");
    if (r.status === 401) return window.location.assign("/sign-in");
    if (r.status === 403) return setStatus("Hub administrators only.");
    setGrid(await r.json());
  }, []);
  useEffect(() => {
    load();
  }, [load]);

  async function change(email: string, poc: Poc, value: Cell) {
    setStatus(`Saving: ${email}, ${poc.name}...`);
    const r = await fetch("/api/admin/allocations", {
      method: value ? "POST" : "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, pocId: poc.id, role: value || undefined }),
    });
    const body = await r.json().catch(() => ({}));
    setStatus(
      r.ok
        ? value
          ? `Saved: ${email} is now ${LABEL[value]} of ${poc.name}.`
          : `Saved: ${email} no longer has access to ${poc.name}.`
        : `Not saved: ${body.error ?? r.status}`,
    );
    load();
  }

  if (!grid)
    return (
      <main className="page">
        <p className="muted">{status || "Loading..."}</p>
      </main>
    );
  const added = newEmail.toLowerCase();
  const users = added && !grid.users.some((u) => u.email === added) ? [...grid.users, { email: added, platformAdmin: false, pocs: {} }] : grid.users;
  const live = grid.pocs.filter((p) => p.status !== "pending").length;

  return (
    <main className="page">
      <h1>Who can open which POC</h1>
      <p className="muted">
        <a href="/">Back to your POCs</a>
      </p>
      <p>
        One row per person, one column per POC. Pick what each person can do in each POC. A change applies straight away and is recorded.
      </p>
      <ul className="legend">
        <li>
          <strong>No access</strong>: cannot open that POC.
        </li>
        <li>
          <strong>Member</strong>: can open and use that POC.
        </li>
        <li>
          <strong>Admin</strong>: can use that POC and open its own settings page. It gives nothing in any other POC.
        </li>
        <li>
          <strong>Hub administrator</strong> (shown under a name): can use this page to allocate access. It is separate from being Admin of a POC.
        </li>
      </ul>
      <p className="muted">
        {live} of {grid.pocs.length} POCs live.
      </p>
      <div className="grid-wrap">
        <table className="alloc">
          <thead>
            <tr>
              <th scope="col">Person</th>
              {grid.pocs.map((p) => (
                <th key={p.id} scope="col">
                  <span className="poc-name">{p.name}</span>
                  {p.status === "pending" ? (
                    <span className="badge">Moving in, not live yet</span>
                  ) : (
                    <a className="poc-host" href={`https://${p.hostname}`}>
                      {p.hostname}
                    </a>
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {users.map((u) => (
              <tr key={u.email}>
                <th scope="row">
                  {u.email}
                  {u.platformAdmin && <span className="tag">Hub administrator</span>}
                </th>
                {grid.pocs.map((p) => {
                  const value = ((u.pocs[p.id] as Cell) ?? "") as Cell;
                  return (
                    <td key={p.id}>
                      <select
                        aria-label={`${u.email}: access to ${p.name}`}
                        value={value}
                        disabled={p.status === "pending"}
                        title={p.status === "pending" ? `${p.name} is not live yet` : undefined}
                        onChange={(e) => change(u.email, p, e.target.value as Cell)}
                      >
                        <option value="">No access</option>
                        <option value="member">Member</option>
                        <option value="admin">Admin</option>
                      </select>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p>
        <label>
          Add a person: <input type="email" placeholder="name@example.com" value={newEmail} onChange={(e) => setNewEmail(e.target.value.trim())} />
        </label>{" "}
        <span className="muted">They appear as a new row; choose their access to save them.</span>
      </p>
      <p className="status" aria-live="polite">
        {status}
      </p>
    </main>
  );
}
EOF
cat > page.tsx <<'EOF'
"use client";

import { useEffect, useState } from "react";

type Launcher = { email: string; platformAdmin: boolean; pocs: { id: string; name: string; description: string; url: string; role: string }[] };

/** Launcher: only the POCs allocated to the signed-in user. */
export default function Home() {
  const [data, setData] = useState<Launcher | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    fetch("/api/launcher").then(async (r) => {
      if (r.status === 401) return window.location.assign("/sign-in");
      if (!r.ok) return setError("You are not set up on the LSV POC hub yet. Ask the State Lifesaving Communications Officer to add you.");
      setData(await r.json());
    });
  }, []);

  return (
    <main className="page">
      <h1>LSV POCs</h1>
      {error && <p className="muted">{error}</p>}
      {data && (
        <>
          <p className="muted">
            Signed in as {data.email}. <a href="/logout">Sign out</a>
          </p>
          <h2>Your POCs</h2>
          {data.pocs.length === 0 ? (
            <p>
              You do not have access to any POC yet.
              {data.platformAdmin ? " As a hub administrator you can give yourself access below." : " Ask the State Lifesaving Communications Officer to add you."}
            </p>
          ) : (
            <ul className="cards">
              {data.pocs.map((p) => (
                <li key={p.id}>
                  <a className="card-title" href={p.url}>
                    {p.name}
                  </a>
                  <span className="tag">{p.role === "admin" ? "You are Admin of this POC" : "You are a Member of this POC"}</span>
                  {p.description && <p className="muted">{p.description}</p>}
                  <p className="muted">{p.url.replace("https://", "")}</p>
                </li>
              ))}
            </ul>
          )}
          {data.platformAdmin && (
            <>
              <h2>Hub administration</h2>
              <p>
                You are a hub administrator. <a href="/admin">Choose who can open which POC</a>.
              </p>
            </>
          )}
        </>
      )}
    </main>
  );
}
