import { describe, expect, test } from "bun:test";
import { createLogger, signSession } from "@lsv-poc/poc-auth";
import { createHubHandlers } from "../src/lib/handlers";
import { seeded } from "./fakes";

const SECRET = "hub-test-secret-that-is-definitely-32-chars!!";
const NOW = 1_800_000_000;
const ORIGIN = "https://poc.nicholaswood.com.au";

function setup() {
  const { store, auth } = seeded();
  const h = createHubHandlers({ store, auth, secret: () => SECRET, origin: ORIGIN, now: () => NOW, log: createLogger("hub", () => {}) });
  const cookie = (email: string) => `__session=${encodeURIComponent(signSession({ app: "hub", uid: `u-${email}`, email, role: "member" }, SECRET, NOW - 60))}`;
  const req = (method: string, path: string, email?: string, body?: unknown, origin = ORIGIN) =>
    new Request(`${ORIGIN}${path}`, {
      method,
      headers: { ...(email ? { cookie: cookie(email) } : {}), "content-type": "application/json", origin },
      body: body ? JSON.stringify(body) : undefined,
    });
  return { store, auth, h, req };
}

describe("ISC-33: launcher lists only the signed-in user's POCs", () => {
  test("member sees oss only, with its URL and role", async () => {
    const { h, req } = setup();
    const res = await h.launcher(req("GET", "/api/launcher", "member@example.com"));
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.pocs).toEqual([{ id: "oss", name: "Service Summary", url: "https://oss.poc.nicholaswood.com.au", role: "member" }]);
  });
  test("an allocation to a POC no longer in the registry is not listed", async () => {
    const { h, req, store } = setup();
    store.users.get("member@example.com")!.pocs.ghost = "admin";
    const body = await (await h.launcher(req("GET", "/api/launcher", "member@example.com"))).json();
    expect(body.pocs.map((p: { id: string }) => p.id)).toEqual(["oss"]);
  });
  test("signed out is 401; a signed cookie for an email with no users doc is 403", async () => {
    const { h, req } = setup();
    expect((await h.launcher(req("GET", "/api/launcher"))).status).toBe(401);
    expect((await h.launcher(req("GET", "/api/launcher", "stranger@example.com"))).status).toBe(403);
  });
});

describe("ISC-34: admin grid refuses non platform admins", () => {
  test("member gets 403 for the grid, grant and revoke; nothing changes", async () => {
