  validation {
    condition     = var.hostname_label == "" || can(regex("^[a-z][a-z0-9-]{1,30}[a-z0-9]$", var.hostname_label))
    error_message = "hostname_label must be a lowercase dns label."
  }
}

# modules/poc-app: everything one POC owns in the shared project.
#
# Every name derives from var.app_id. The calling root lives in the POC's
# own repo with state prefix apps/<app_id>, so a POC is deployed and removed
# on its own. Shapes ported from LIMSOC Permission Assist
# infra/terraform/main.tf (origin/main efc934f).
#
# Not here, by design:
#   - Firestore rules (project-wide permission; terraform/platform releases
#     deny-all for poc-<app_id> unless registered as client_access).
#   - Any project-level role for the runtime account (see the one
#     database-conditioned binding below and why).

locals {
  hostname     = "${var.hostname_label == "" ? var.app_id : var.hostname_label}.${var.poc_domain}"
  app_url      = "https://${local.hostname}"
  service_name = "poc-${var.app_id}"
  database     = "poc-${var.app_id}"
  site_id      = "${var.site_prefix}-${var.app_id}"
  run_sa       = "${var.app_id}-run"
  deploy_sa    = "${var.app_id}-deploy"
  sched_sa     = "${var.app_id}-sched"
  labels       = { poc = var.app_id }
}

# ── Firestore: the POC's own named database ──────────────────────────────────
resource "google_firestore_database" "app" {
  project                           = var.project_id
  name                              = local.database
  location_id                       = var.region
  type                              = "FIRESTORE_NATIVE"
  delete_protection_state           = "DELETE_PROTECTION_ENABLED"
  deletion_policy                   = "ABANDON"
  point_in_time_recovery_enablement = "POINT_IN_TIME_RECOVERY_DISABLED"
}

# ── Service accounts ─────────────────────────────────────────────────────────
resource "google_service_account" "run" {
  project      = var.project_id
  account_id   = local.run_sa
  display_name = "${var.display_name} runtime"
}

resource "google_service_account" "deploy" {
  project      = var.project_id
  account_id   = local.deploy_sa
  display_name = "${var.display_name} GitHub deploy"
}

# ── Runtime account: resource-level grants only ──────────────────────────────
# Its own database. Firestore offers no IAM policy on a database resource, so
# the narrowest possible grant is this project binding with a condition that
# matches exactly one database name. It confers nothing on any other database,
# on the platform database, or on any other service. This is the module's
# only google_project_iam_member and it always carries the condition.
resource "google_project_iam_member" "run_own_database" {
  project = var.project_id
  role    = "roles/datastore.user"
  member  = "serviceAccount:${google_service_account.run.email}"
  condition {
    title       = "only-${local.database}"
    description = "Firestore database ${local.database} only"
    expression  = "resource.name == \"projects/${var.project_id}/databases/${local.database}\""
  }
}

# Custom tokens (browser Firestore sign-in) are signed through IAM signBlob as
# the runtime account itself: a grant on the account, not the project.
resource "google_service_account_iam_member" "run_self_sign" {
  count              = var.client_access ? 1 : 0
  service_account_id = google_service_account.run.name
  role               = "roles/iam.serviceAccountTokenCreator"
  member             = "serviceAccount:${google_service_account.run.email}"
}

# ── Secrets, named <app_id>-* ────────────────────────────────────────────────
resource "random_password" "session" {
  length  = 64
  special = false
}

resource "google_secret_manager_secret" "session" {
  project   = var.project_id
  secret_id = "${var.app_id}-session-signing"
  labels    = local.labels
  replication {
    auto {}
  }
}

resource "google_secret_manager_secret_version" "session" {
  secret      = google_secret_manager_secret.session.id
  secret_data = random_password.session.result
}

resource "google_secret_manager_secret_iam_member" "run_session" {
  project   = var.project_id
  secret_id = google_secret_manager_secret.session.secret_id
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.run.email}"
}

# ── Images ───────────────────────────────────────────────────────────────────
resource "google_artifact_registry_repository" "app" {
  project       = var.project_id
  location      = var.region
  repository_id = var.app_id
  format        = "DOCKER"
  labels        = local.labels
  cleanup_policies {
    id     = "keep-recent"
    action = "KEEP"
    most_recent_versions {
      keep_count = 3
    }
  }
  cleanup_policies {
    id     = "delete-older"
    action = "DELETE"
    condition {
      older_than = "86400s"
    }
  }
}

# ── Cloud Run ────────────────────────────────────────────────────────────────
resource "google_cloud_run_v2_service" "app" {
  project             = var.project_id
  name                = local.service_name
  location            = var.region
  labels              = local.labels
  deletion_protection = true
  # ISC-24, the proven pattern (Permission Assist and AccessBuddy):
  # ingress ALL plus a public invoker (below). Firebase Hosting's rewrite is
  # the front door and is not an internal caller, so internal-only ingress
  # or an authenticated invoker would block it. The host enforces sign-in
  # itself on every route except /sign-in, /auth/*, /api/auth/* and
  # /api/health; the run.app address therefore exposes nothing extra.
  ingress = "INGRESS_TRAFFIC_ALL"

  template {
    service_account                  = google_service_account.run.email
    max_instance_request_concurrency = 80
    timeout                          = "60s"
    labels                           = local.labels
    scaling {
      min_instance_count = 0
      max_instance_count = 2
    }
    containers {
      image = var.initial_image
      ports {
        container_port = 3000
      }
      resources {
        limits            = { cpu = "1", memory = "512Mi" }
        cpu_idle          = true
        startup_cpu_boost = true
      }
      startup_probe {
        http_get {
          path = "/api/health"
          port = 3000
        }
        initial_delay_seconds = 2
        period_seconds        = 3
        failure_threshold     = 10
      }
      env {
        name  = "APP_ID"
        value = var.app_id
      }
      env {
        name  = "FIRESTORE_DATABASE"
        value = google_firestore_database.app.name
      }
      env {
        name  = "NEXT_PUBLIC_APP_URL"
        value = local.app_url
      }
      env {
        name  = "NEXT_PUBLIC_FIREBASE_PROJECT_ID"
        value = var.project_id
      }
      env {
        name  = "TRUSTED_PROXY_HOPS"
        value = "1"
      }
      env {
        name  = "JOB_INVOKER"
        value = length(var.scheduled_jobs) > 0 ? google_service_account.sched[0].email : ""
      }
      env {
        name = "SESSION_SIGNING_SECRET"
        value_source {
          secret_key_ref {
            secret  = google_secret_manager_secret.session.secret_id
            version = "latest"
          }
        }
      }
    }
  }

  lifecycle {
    # CI sets the image on each release; Terraform owns everything else.
    ignore_changes = [template[0].containers[0].image, client, client_version, scaling]
  }
  depends_on = [google_secret_manager_secret_version.session, google_secret_manager_secret_iam_member.run_session]
}

resource "google_cloud_run_v2_service_iam_member" "public" {
  project  = var.project_id
  name     = google_cloud_run_v2_service.app.name
  location = var.region
  role     = "roles/run.invoker"
  member   = "allUsers"
}

# ── Front door: Firebase Hosting on <app_id>.<poc_domain> ────────────────────
# Cloud Run domain mappings are not offered in australia-southeast1. Hosting
# forwards only the __session cookie, which is why poc-auth uses that name.
resource "google_firebase_hosting_site" "app" {
  provider = google-beta
  project  = var.project_id
  site_id  = local.site_id
}

resource "google_firebase_hosting_version" "app" {
  provider = google-beta
  site_id  = google_firebase_hosting_site.app.site_id
  config {
    rewrites {
      glob = "**"
      run {
        service_id = google_cloud_run_v2_service.app.name
        region     = var.region
      }
    }
  }
}

resource "google_firebase_hosting_release" "app" {
  provider     = google-beta
  site_id      = google_firebase_hosting_site.app.site_id
  version_name = google_firebase_hosting_version.app.name
  message      = "Rewrite everything to ${local.service_name}"
}

resource "google_firebase_hosting_custom_domain" "app" {
  provider              = google-beta
  project               = var.project_id
  site_id               = google_firebase_hosting_site.app.site_id
  custom_domain         = local.hostname
  wait_dns_verification = false
}

# ── DNS in the delegated sub-zone ────────────────────────────────────────────
resource "google_dns_record_set" "app" {
  project      = var.project_id
  managed_zone = var.dns_zone_name
  name         = "${local.hostname}."
  type         = "CNAME"
  ttl          = 300
  rrdatas      = ["${local.site_id}.web.app."]
}

# ── GitHub deploy identity, pinned ───────────────────────────────────────────
resource "google_iam_workload_identity_pool_provider" "github" {
  project                            = var.project_id
  workload_identity_pool_id          = var.workload_identity_pool_id
  workload_identity_pool_provider_id = "${var.app_id}-gh"
  display_name                       = "${var.app_id} GitHub"
  attribute_mapping = {
    "google.subject"          = "assertion.sub"
    "attribute.repository_id" = "assertion.repository_id"
    "attribute.ref"           = "assertion.ref"
  }
  # Repository id, owner id and the main branch. Pull requests and other
  # branches cannot obtain a token.
  attribute_condition = "assertion.repository_id == \"${var.github_repository_id}\" && assertion.repository_owner_id == \"${var.github_owner_id}\" && assertion.ref == \"refs/heads/main\""
  oidc {
    issuer_uri = "https://token.actions.githubusercontent.com"
  }
}

resource "google_service_account_iam_member" "deploy_wif" {
  service_account_id = google_service_account.deploy.name
  role               = "roles/iam.workloadIdentityUser"
  member             = "principalSet://iam.googleapis.com/projects/${data.google_project.this.number}/locations/global/workloadIdentityPools/${var.workload_identity_pool_id}/attribute.repository_id/${var.github_repository_id}"
}

# Deploy account: its own image repository and its own service, nothing else.
resource "google_artifact_registry_repository_iam_member" "deploy_push" {
  project    = var.project_id
  location   = google_artifact_registry_repository.app.location
  repository = google_artifact_registry_repository.app.name
  role       = "roles/artifactregistry.writer"
  member     = "serviceAccount:${google_service_account.deploy.email}"
}

resource "google_cloud_run_v2_service_iam_member" "deploy_run" {
  project  = var.project_id
  name     = google_cloud_run_v2_service.app.name
  location = var.region
  role     = "roles/run.developer"
  member   = "serviceAccount:${google_service_account.deploy.email}"
}

resource "google_service_account_iam_member" "deploy_acts_as_run" {
  service_account_id = google_service_account.run.name
  role               = "roles/iam.serviceAccountUser"
  member             = "serviceAccount:${google_service_account.deploy.email}"
}

data "google_project" "this" {
  project_id = var.project_id
}

# ── Scheduled jobs (only when declared) ──────────────────────────────────────
resource "google_service_account" "sched" {
  count        = length(var.scheduled_jobs) > 0 ? 1 : 0
  project      = var.project_id
  account_id   = local.sched_sa
  display_name = "${var.display_name} scheduler"
}

resource "google_cloud_scheduler_job" "job" {
  for_each  = { for j in var.scheduled_jobs : j.name => j }
  project   = var.project_id
  region    = var.region
  name      = "${var.app_id}-${each.key}"
  schedule  = each.value.schedule
  time_zone = "Australia/Melbourne"
  http_target {
    http_method = "POST"
    uri         = "${google_cloud_run_v2_service.app.uri}${each.value.path}"
    oidc_token {
      service_account_email = google_service_account.sched[0].email
      audience              = google_cloud_run_v2_service.app.uri
    }
  }
  retry_config {
    retry_count = 1
  }
}

# Per-app uptime, error, sign-in and job alerting. All alerts go to the
# platform's email channel. Log filters match the structured lines that
# packages/poc-auth writes (jsonPayload.app_id, jsonPayload.event).

resource "google_monitoring_uptime_check_config" "health" {
  project      = var.project_id
  display_name = "${var.app_id} /api/health"
  timeout      = "10s"
  period       = "300s"
  http_check {
    path         = "/api/health"
    port         = 443
    use_ssl      = true
    validate_ssl = true
  }
  monitored_resource {
    type = "uptime_url"
    labels = {
      project_id = var.project_id
      host       = local.hostname
    }
  }
}

resource "google_monitoring_alert_policy" "uptime" {
  project               = var.project_id
  display_name          = "${var.app_id}: health check failing"
  combiner              = "OR"
  notification_channels = [var.notification_channel]
  conditions {
    display_name = "${var.app_id} uptime"
    condition_threshold {
      filter          = "metric.type=\"monitoring.googleapis.com/uptime_check/check_passed\" AND resource.type=\"uptime_url\" AND metric.label.check_id=\"${google_monitoring_uptime_check_config.health.uptime_check_id}\""
      comparison      = "COMPARISON_GT"
      threshold_value = 1
      duration        = "600s"
      aggregations {
        alignment_period     = "1200s"
        per_series_aligner   = "ALIGN_NEXT_OLDER"
        cross_series_reducer = "REDUCE_COUNT_FALSE"
        group_by_fields      = ["resource.label.host"]
      }
      trigger {
        count = 1
      }
    }
  }
  user_labels = local.labels
}

resource "google_monitoring_alert_policy" "errors_5xx" {
  project               = var.project_id
  display_name          = "${var.app_id}: 5xx rate"
  combiner              = "OR"
  notification_channels = [var.notification_channel]
  conditions {
    display_name = "${var.app_id} 5xx responses"
    condition_threshold {
      filter          = "metric.type=\"run.googleapis.com/request_count\" AND resource.type=\"cloud_run_revision\" AND resource.label.service_name=\"${local.service_name}\" AND metric.label.response_code_class=\"5xx\""
      comparison      = "COMPARISON_GT"
      threshold_value = var.error_rate_threshold
      duration        = "300s"
      aggregations {
        alignment_period     = "300s"
        per_series_aligner   = "ALIGN_RATE"
        cross_series_reducer = "REDUCE_SUM"
      }
    }
  }
  user_labels = local.labels
}

resource "google_logging_metric" "signin_failures" {
  project = var.project_id
  name    = "${var.app_id}-signin-failures"
  filter  = "resource.type=\"cloud_run_revision\" AND resource.labels.service_name=\"${local.service_name}\" AND jsonPayload.app_id=\"${var.app_id}\" AND jsonPayload.event=\"auth.signin_failed\""
  metric_descriptor {
    metric_kind = "DELTA"
    value_type  = "INT64"
    unit        = "1"
  }
}

resource "google_monitoring_alert_policy" "signin_spike" {
  project               = var.project_id
  display_name          = "${var.app_id}: sign-in failure spike"
  combiner              = "OR"
  notification_channels = [var.notification_channel]
  conditions {
    display_name = "${var.app_id} refused sign-ins"
    condition_threshold {
      filter          = "metric.type=\"logging.googleapis.com/user/${google_logging_metric.signin_failures.name}\" AND resource.type=\"cloud_run_revision\""
      comparison      = "COMPARISON_GT"
      threshold_value = var.signin_failure_threshold
      duration        = "0s"
      aggregations {
        alignment_period     = "600s"
        per_series_aligner   = "ALIGN_SUM"
        cross_series_reducer = "REDUCE_SUM"
      }
    }
  }
  user_labels = local.labels
}

# Only when jobs are declared: a job that logs job.failed, or a scheduler
# attempt that did not succeed.
resource "google_logging_metric" "job_failures" {
  count   = length(var.scheduled_jobs) > 0 ? 1 : 0
  project = var.project_id
  name    = "${var.app_id}-job-failures"
  filter  = "(resource.type=\"cloud_run_revision\" AND resource.labels.service_name=\"${local.service_name}\" AND jsonPayload.app_id=\"${var.app_id}\" AND jsonPayload.event=\"job.failed\") OR (resource.type=\"cloud_scheduler_job\" AND resource.labels.job_id=~\"^${var.app_id}-\" AND severity>=ERROR)"
  metric_descriptor {
    metric_kind = "DELTA"
    value_type  = "INT64"
    unit        = "1"
  }
}

resource "google_monitoring_alert_policy" "job_failure" {
  count                 = length(var.scheduled_jobs) > 0 ? 1 : 0
  project               = var.project_id
  display_name          = "${var.app_id}: scheduled job failed"
  combiner              = "OR"
  notification_channels = [var.notification_channel]
  conditions {
    display_name = "${var.app_id} job failures"
    condition_threshold {
      filter          = "metric.type=\"logging.googleapis.com/user/${google_logging_metric.job_failures[0].name}\""
      comparison      = "COMPARISON_GT"
      threshold_value = 0
      duration        = "0s"
      aggregations {
        alignment_period     = "300s"
        per_series_aligner   = "ALIGN_SUM"
        cross_series_reducer = "REDUCE_SUM"
      }
    }
  }
  user_labels = local.labels
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    google      = { source = "hashicorp/google", version = "~> 6.0" }
    google-beta = { source = "hashicorp/google-beta", version = "~> 6.0" }
    random      = { source = "hashicorp/random", version = "~> 3.6" }
  }
}

output "app_url" {
  value = local.app_url
}

output "hostname" {
  value = local.hostname
}

output "cloud_run_url" {
  value = google_cloud_run_v2_service.app.uri
}

output "service_name" {
  value = google_cloud_run_v2_service.app.name
}

output "database" {
  value = google_firestore_database.app.name
}

output "run_service_account" {
  value = google_service_account.run.email
}

output "deploy_service_account" {
  description = "DEPLOY_SERVICE_ACCOUNT in the app's deploy workflow"
  value       = google_service_account.deploy.email
}

output "workload_identity_provider" {
  description = "WIF_PROVIDER in the app's deploy workflow"
  value       = google_iam_workload_identity_pool_provider.github.name
}

output "artifact_registry" {
  value = "${var.region}-docker.pkg.dev/${var.project_id}/${google_artifact_registry_repository.app.repository_id}"
}

output "firebase_api_key" {
  value = var.firebase_api_key
}

output "firebase_app_id" {
  value = var.firebase_app_id
}

output "custom_domain_required_dns_updates" {
  description = "What Firebase Hosting asks for; the CNAME above should satisfy it."
  value       = google_firebase_hosting_custom_domain.app.required_dns_updates
}

output "custom_domain_state" {
  value = "${google_firebase_hosting_custom_domain.app.host_state} / ${google_firebase_hosting_custom_domain.app.ownership_state} / cert ${try(google_firebase_hosting_custom_domain.app.cert[0].state, "none")}"
}
