import { createHmac, timingSafeEqual } from "node:crypto";
import { parseRole, type AppRole } from "./claims";

/**
 * The `__session` cookie: an HMAC-signed statement "uid U, email E, role R
 * in app A, signed in at T". Ported from Permission Assist's
 * signOtpSession / verifyOtpSessionCookie (host/src/lib/auth.ts), itself
 * from AccessBuddy, with the app id and role added to the payload.
 *
 * Why not Firebase session cookies: creating and revocation-checking those
 * needs Firebase Auth admin, which is a project-level role. Only the hub may
 * hold it, so POC hosts verify the ID token once (public keys, no IAM) and
 * sign their own cookie with a per-app secret. Revocation reaches them as
 * an override document the hub writes into the app's own database.
 *
 * Cookie name is `__session` because Firebase Hosting forwards only that one.
 */
export const SESSION_COOKIE_NAME = "__session";
/** 14 days, as in AccessBuddy and Permission Assist. */
export const SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 14;
export const MIN_SECRET_LENGTH = 32;
const PREFIX = "poc1";

export type SessionClaims = { app: string; uid: string; email: string; role: AppRole };
export type SessionPayload = SessionClaims & { iat: number; exp: number };

function checkSecret(secret: string): string {
  if (!secret || secret.length < MIN_SECRET_LENGTH) {
    throw new Error(`SESSION_SIGNING_SECRET is required and must be at least ${MIN_SECRET_LENGTH} characters. Refusing to sign or verify sessions without it.`);
  }
  return secret;
}

export function signSession(claims: SessionClaims, secret: string, nowSeconds = Math.floor(Date.now() / 1000)): string {
  const payload: SessionPayload = { ...claims, email: claims.email.toLowerCase().trim(), iat: nowSeconds, exp: nowSeconds + SESSION_MAX_AGE_SECONDS };
  const body = JSON.stringify(payload);
  const sig = createHmac("sha256", checkSecret(secret)).update(body).digest("base64url");
  return `${PREFIX}.${Buffer.from(body).toString("base64url")}.${sig}`;
}

export function verifySession(value: string | undefined, secret: string, nowSeconds = Math.floor(Date.now() / 1000)): SessionPayload | null {
  if (!value) return null;
  const parts = value.split(".");
  if (parts.length !== 3 || parts[0] !== PREFIX) return null;
  const body = Buffer.from(parts[1], "base64url").toString();
  const expected = createHmac("sha256", checkSecret(secret)).update(body).digest("base64url");
  const provided = parts[2];
  if (provided.length !== expected.length || !timingSafeEqual(Buffer.from(provided), Buffer.from(expected))) return null;
  let p: Record<string, unknown>;
  try {
    p = JSON.parse(body);
  } catch {
    return null;
  }
  const role = parseRole(p.role);
  if (typeof p.exp !== "number" || p.exp < nowSeconds) return null;
  if (typeof p.iat !== "number" || typeof p.uid !== "string" || !p.uid || typeof p.app !== "string" || typeof p.email !== "string" || !role) return null;
  return { app: p.app, uid: p.uid, email: p.email, role, iat: p.iat, exp: p.exp };
}

/** Set-Cookie value with the flags AccessBuddy and Permission Assist use. */
export function sessionSetCookie(value: string, secure: boolean): string {
  return [`${SESSION_COOKIE_NAME}=${encodeURIComponent(value)}`, "Path=/", `Max-Age=${SESSION_MAX_AGE_SECONDS}`, "HttpOnly", "SameSite=Lax", ...(secure ? ["Secure"] : [])].join("; ");
}

export function clearSessionCookie(secure: boolean): string {
  return [`${SESSION_COOKIE_NAME}=`, "Path=/", "Max-Age=0", "HttpOnly", "SameSite=Lax", ...(secure ? ["Secure"] : [])].join("; ");
}

export function readCookie(header: string | null | undefined, name = SESSION_COOKIE_NAME): string | undefined {
  if (!header) return undefined;
  for (const part of header.split(";")) {
    const i = part.indexOf("=");
    if (i < 0) continue;
    if (part.slice(0, i).trim() === name) {
      try {
        return decodeURIComponent(part.slice(i + 1).trim());
      } catch {
        return undefined;
      }
    }
  }
  return undefined;
}
import { roleFromClaims, type AppRole } from "./claims";
import { LOG_EVENTS, type Logger } from "./log";
import { getClientIp, type RateLimiter } from "./rate-limit";
import { clearSessionCookie, sessionSetCookie, signSession } from "./session";

/** The fields of a verified Firebase ID token this package reads. Custom claims sit at the top level. */
export type DecodedIdToken = {
  uid: string;
  email?: string;
  email_verified?: boolean;
  auth_time: number;
  [claim: string]: unknown;
};

export type SessionExchangeOptions = {
  appId: string;
  secret: () => string;
  /** Verify signature, audience, issuer and expiry. Needs no IAM: Google's public keys only. */
  verifyIdToken: (idToken: string) => Promise<DecodedIdToken>;
  /** Defaults to the claim contract: poc_<appId> of "member" or "admin". The hub supplies its own. */
  authorise?: (decoded: DecodedIdToken) => Promise<AppRole | null> | AppRole | null;
  rateLimiter: RateLimiter;
  log: Logger;
  secureCookie: boolean;
  /** A sign-in older than this is refused, so a stolen long-lived ID token cannot mint a fresh session. */
  maxAuthAgeSeconds?: number;
  trustedProxyHops?: number;
  now?: () => number; // epoch seconds
};

const json = (status: number, body: unknown, headers: Record<string, string> = {}) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", "Cache-Control": "private, no-store", ...headers } });

/**
 * POST /api/auth/session { idToken } -> 200 and the __session cookie, or a
 * refusal and no cookie. The same step as Permission Assist's
 * app/api/auth/session/route.ts, with the allow-list lookup replaced by the
 * app-scoped claim. Framework-free (Web Request/Response) so Next.js route
 * handlers and tests call it the same way.
 */
export function createSessionExchange(o: SessionExchangeOptions) {
  const now = o.now ?? (() => Math.floor(Date.now() / 1000));
  const maxAge = o.maxAuthAgeSeconds ?? 5 * 60;
  const authorise = o.authorise ?? ((d: DecodedIdToken) => roleFromClaims(d, o.appId));
  const refuse = (status: number, reason: string, extra: Record<string, unknown> = {}) => {
    o.log.warn("sign-in refused", { event: LOG_EVENTS.signInFailed, reason, status, ...extra });
    return json(status, { error: status === 403 ? "No access to this app" : "Sign-in failed" });
  };

  return async function POST(request: Request): Promise<Response> {
    const ip = getClientIp(request, o.trustedProxyHops);
    const rl = await o.rateLimiter.check(`ip:${ip}`, { namespace: "auth.session", windowSeconds: 60, max: 20 });
    if (!rl.ok) return refuse(429, "rate_limited", { retryAfter: rl.retryAfter });

    const body = (await request.json().catch(() => null)) as { idToken?: unknown } | null;
    const idToken = body?.idToken;
    if (typeof idToken !== "string" || !idToken) return json(400, { error: "Token required" });

    let decoded: DecodedIdToken;
    try {
      decoded = await o.verifyIdToken(idToken);
    } catch (err) {
      return refuse(401, "invalid_token", { err });
    }
    const email = (decoded.email ?? "").toLowerCase().trim();
    if (!email || decoded.email_verified !== true) return refuse(401, "email_unverified", { uid: decoded.uid });
    if (typeof decoded.auth_time !== "number" || now() - decoded.auth_time > maxAge) return refuse(401, "stale_sign_in", { uid: decoded.uid });

    let role: AppRole | null;
    try {
      role = await authorise(decoded);
    } catch (err) {
      o.log.error("authorise failed", { err, uid: decoded.uid });
      return json(503, { error: "Try again shortly" });
    }
    if (!role) return refuse(403, "no_app_claim", { uid: decoded.uid });

    const cookie = signSession({ app: o.appId, uid: decoded.uid, email, role }, o.secret(), now());
    o.log.info("sign-in", { event: LOG_EVENTS.signInOk, uid: decoded.uid, role });
    return json(200, { success: true, role }, { "Set-Cookie": sessionSetCookie(cookie, o.secureCookie) });
  };
}

/** DELETE /api/auth/session and GET /logout both clear the cookie. */
export function logoutResponse(redirectTo: string | null, secureCookie: boolean): Response {
  const headers: Record<string, string> = { "Set-Cookie": clearSessionCookie(secureCookie), "Cache-Control": "private, no-store" };
  if (redirectTo) return new Response(null, { status: 303, headers: { ...headers, Location: redirectTo } });
  return json(200, { success: true }, headers);
}
// Framework-free core. Firebase adapters live in "@lsv-poc/poc-auth/firebase"
// so tests and edge middleware never load firebase-admin.
export * from "./claims";
export * from "./session";
export * from "./access";
export * from "./exchange";
export * from "./rate-limit";
export * from "./log";
export * from "./csp";
export * from "./safe-redirect";
