import type { AuthAdmin, PlatformStore, UserRecord } from "./types";

/**
 * The hub's API, framework-free (Web Request -> Response) so the Next.js
 * routes are one-line wrappers and the tests call exactly what production
 * calls.
 *
 * Allocation has one source of truth: users/<email> in the platform
 * database. The `poc_<id>` claim and the POC's platformAccess/<uid> override
 * are derived from it, written after it, and repairable from it
 * (scripts/resync-claims.ts).
 */
export type HubDeps = {
  store: PlatformStore;
  auth: AuthAdmin;
  secret: () => string;
  /** The hub's public origin; mutating requests must come from it. */
  origin: string;
  pocDomain?: string;
  log: Logger;
  now?: () => number; // epoch seconds
};

const EMAIL = /^[^\s@]{1,64}@[^\s@]{1,190}\.[^\s@]{2,}$/;
const json = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json", "Cache-Control": "private, no-store" } });

import { createLogger, createRateLimiter, createSessionExchange } from "@lsv-poc/poc-auth";
import { adminApp, appDb, FirestoreRateLimitStore, verifyIdToken } from "@lsv-poc/poc-auth/firebase";
import { getAuth } from "firebase-admin/auth";
import { FirestorePlatformStore } from "./firestore-store";
import { createHubHandlers, hubAuthorise } from "./handlers";
import type { AuthAdmin } from "./types";

/** Production wiring. Built lazily on first request so `next build` needs no credentials. */
export const log = createLogger("hub");

function secret(): string {
  return process.env.SESSION_SIGNING_SECRET ?? "";
}
const origin = () => process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";

/** The hub's Firebase Auth admin: the only place in the platform that holds it. */
function authAdmin(): AuthAdmin {
  const auth = getAuth(adminApp());
  return {
    async getUserByEmail(email) {
      try {
        const u = await auth.getUserByEmail(email);
        return { uid: u.uid, customClaims: u.customClaims ?? {} };
      } catch (e) {
        if ((e as { code?: string }).code === "auth/user-not-found") return null;
        throw e;
      }
    },
    async createUser(email) {
      // Email only. No password is ever set on any account in this pool.
      const u = await auth.createUser({ email, emailVerified: false });
      return { uid: u.uid };
    },
    setCustomUserClaims: (uid, claims) => auth.setCustomUserClaims(uid, claims),
    revokeRefreshTokens: (uid) => auth.revokeRefreshTokens(uid),
  };
}

let _handlers: ReturnType<typeof createHubHandlers> | null = null;
export function handlers() {
  _handlers ??= createHubHandlers({
    store: new FirestorePlatformStore(),
    auth: authAdmin(),
    secret,
    origin: origin(),
    pocDomain: process.env.POC_DOMAIN,
    log,
  });
  return _handlers;
}

let _exchange: ReturnType<typeof createSessionExchange> | null = null;
export function sessionExchange() {
  _exchange ??= createSessionExchange({
    appId: "hub",
    secret,
    verifyIdToken,
    authorise: hubAuthorise(new FirestorePlatformStore()),
    rateLimiter: createRateLimiter(new FirestoreRateLimitStore(() => appDb("platform"))),
    log,
    secureCookie: process.env.NODE_ENV === "production",
  });
  return _exchange;
}
