cd ~/Documents/workspace/projects/lsv-poc-platform/code && bun -e '
const RP=(deployFile,what)=>`# Same release flow as AccessBuddy: release-please keeps a release pull
# request open on main; merging it cuts a version and a GitHub release, and
# that release deploys ${what}. Nothing deploys on an ordinary merge.
# Needs: conventional commit messages (feat:, fix:), the repository setting
# "Allow GitHub Actions to create and approve pull requests", and a
# \`production\` environment.
name: Release Please

on:
  push:
    branches: [main]

permissions:
  contents: write
  pull-requests: write
  id-token: write

jobs:
  release-please:
    runs-on: ubuntu-latest
    outputs:
      release_created: \${{ steps.release.outputs.release_created }}
      version: \${{ steps.release.outputs.version }}
    steps:
      - uses: googleapis/release-please-action@v4
        id: release

  deploy:
    name: Deploy
    needs: [release-please]
    if: \${{ needs.release-please.outputs.release_created == \x27true\x27 }}
    uses: ./.github/workflows/${deployFile}
    with:
      version: \${{ needs.release-please.outputs.version }}
    secrets: inherit
`;
const ON=`on:
  # Called by release-please.yml when a release is cut.
  workflow_call:
    inputs:
      version:
        required: true
        type: string
  # Manual redeploy of a given version label from the current main.
  workflow_dispatch:
    inputs:
      version:
        description: Version label to report at /api/health
        required: true
        type: string
`;
const cfg=JSON.stringify({packages:{".":{"release-type":"simple","version-file":"VERSION"}}},null,2)+"\n";
const man=JSON.stringify({".":"0.1.0"},null,2)+"\n";
for (const [root,deploy,what] of [[".","deploy-hub.yml","the hub"],["template/host","deploy.yml","this POC"]]) {
  await Bun.write(`${root}/release-please-config.json`,cfg); await Bun.write(`${root}/.release-please-manifest.json`,man); await Bun.write(`${root}/VERSION`,"0.1.0\n");
  await Bun.write(`${root}/.github/workflows/release-please.yml`,RP(deploy,what));
  const f=`${root}/.github/workflows/${deploy}`; let s=await Bun.file(f).text();
  const a=s.indexOf("on:\n"); const b=s.indexOf("\nconcurrency:");
  if(a<0||b<0) throw new Error("shape "+f);
  s=s.slice(0,a)+ON+s.slice(b);
  s=s.replaceAll("--build-arg APP_VERSION=${{ github.sha }}","--build-arg APP_VERSION=${{ inputs.version }}").replace(`grep -q \x27"version":"\${{ github.sha }}"\x27`,`grep -q \x27"version":"\${{ inputs.version }}"\x27`);
  s=s.replace(/^# Push to main[^\n]*\n/, m=>"# Runs when release-please cuts a release (see release-please.yml), not on an ordinary push.\n"+m.replace("Push to main","On release"));
  if(!s.includes("inputs.version }}\"\x27")) throw new Error("verify step not updated "+f);
  await Bun.write(f,s);
}
let f=".github/workflows/ci.yml", s=await Bun.file(f).text();
const i=s.indexOf("  # Also on pushes"); const j=s.indexOf("\nconcurrency:");
if(i>0) s=s.slice(0,i).trimEnd()+"\n"+s.slice(j); await Bun.write(f,s);
' && head -12 .github/workflows/ci.yml | sed -n 4,9p && sed -n 1,22p .github/workflows/deploy-hub.yml && rg -n "inputs.version|github.sha" template/host/.github/workflows/deploy.yml | cut -c1-120

