/**
 * Single use for hub handoff tickets: records the ticket id in the app\x27s own
 * database with create(), which fails if the document already exists, so two
 * requests carrying the same ticket cannot both succeed. Documents carry
 * expiresAt so a Firestore TTL policy can clear them.
 */
export function firestoreTicketStore(db: () => Firestore, collection = "handoffTickets") {
  return async (jti: string, expiresAtSeconds: number): Promise<boolean> => {
    try {
      await db().collection(collection).doc(jti).create({ expiresAt: new Date(expiresAtSeconds * 1000), usedAt: new Date() });
      return true;
    } catch (e) {
      const code = (e as { code?: number | string }).code;
      if (code === 6 || code === "already-exists" || code === "ALREADY_EXISTS") return false;
      throw e;
    }
  };
}
`; await Bun.write(f,s);
await Bun.write("packages/poc-auth/test/handoff.test.ts", `import { describe, expect, test } from "bun:test";
import { generateKeyPairSync } from "node:crypto";
import { createHandoffReceiver, createLogger, handoffPublicKey, HANDOFF_TTL_SECONDS, hubKeyFetcher, readCookie, signHandoff, verifyHandoff, verifySession } from "../src";

const pair = () => {
  const k = generateKeyPairSync("ed25519");
  return { priv: k.privateKey.export({ type: "pkcs8", format: "pem" }).toString(), pub: k.publicKey.export({ type: "spki", format: "pem" }).toString() };
};
const hub = pair();
const other = pair();
const NOW = 1_800_000_000;
const SECRET = "app-test-secret-that-is-definitely-32-chars!!";
const claims = { aud: "permissions", sub: "uid-1", email: "Member@Example.com", role: "member" as const };

describe("hub handoff ticket", () => {
  test("round trips, lower-cases the email, and the public key derives from the private key", () => {
    expect(handoffPublicKey(hub.priv)).toBe(hub.pub);
    const t = verifyHandoff(signHandoff(claims, hub.priv, NOW), hub.pub, "permissions", NOW + 5);
    expect(t).toMatchObject({ aud: "permissions", sub: "uid-1", email: "member@example.com", role: "member" });
    expect(t!.exp - t!.iat).toBe(HANDOFF_TTL_SECONDS);
  });
  test("is valid for one app only", () => {
    expect(verifyHandoff(signHandoff(claims, hub.priv, NOW), hub.pub, "oss", NOW)).toBeNull();
  });
  test("expires after 60 seconds and is not accepted before it was issued", () => {
    const v = signHandoff(claims, hub.priv, NOW);
    expect(verifyHandoff(v, hub.pub, "permissions", NOW + 60)).not.toBeNull();
    expect(verifyHandoff(v, hub.pub, "permissions", NOW + 61)).toBeNull();
    expect(verifyHandoff(v, hub.pub, "permissions", NOW - 30)).toBeNull();
  });
  test("a ticket signed by any other key is refused, so a POC cannot mint one", () => {
    expect(verifyHandoff(signHandoff(claims, other.priv, NOW), hub.pub, "permissions", NOW)).toBeNull();
  });
  test("tampering with the role or audience breaks the signature", () => {
    const [p, body, sig] = signHandoff(claims, hub.priv, NOW).split(".");
    const forged = Buffer.from(JSON.stringify({ ...JSON.parse(Buffer.from(body, "base64url").toString()), role: "admin" })).toString("base64url");
    expect(verifyHandoff([p, forged, sig].join("."), hub.pub, "permissions", NOW)).toBeNull();
  });
  test("garbage, a session cookie, or an oversized value is refused", () => {
    for (const v of ["", "poch1.a.b", "poc1.x.y", "x".repeat(3000), null, undefined]) expect(verifyHandoff(v, hub.pub, "permissions", NOW)).toBeNull();
  });
  test("refuses to sign with a key that is not Ed25519", () => {
    const rsa = generateKeyPairSync("rsa", { modulusLength: 2048 }).privateKey.export({ type: "pkcs8", format: "pem" }).toString();
    expect(() => signHandoff(claims, rsa, NOW)).toThrow();
  });
});

function receiver(opts: { key?: (force?: boolean) => Promise<string>; used?: Set<string> } = {}) {
  const used = opts.used ?? new Set<string>();
  return createHandoffReceiver({
    appId: "permissions",
    secret: () => SECRET,
    appUrl: "https://permissions.poc.nicholaswood.com.au",
    hubPublicKey: opts.key ?? (async () => hub.pub),
    consumeTicket: async (jti) => (used.has(jti) ? false : (used.add(jti), true)),
    log: createLogger("permissions", () => {}),
    secureCookie: true,
    now: () => NOW,
  });
}
const get = (ticket: string | null, redirect?: string) =>
  new Request(\`https://run.internal/auth/handoff?\${new URLSearchParams({ ...(ticket ? { ticket } : {}), ...(redirect ? { redirect } : {}) })}\`);

describe("handoff receiver", () => {
  test("a good ticket sets this app\x27s own session cookie and goes to the requested path on the app\x27s own origin", async () => {
    const res = await receiver()(get(signHandoff(claims, hub.priv, NOW), "/reports?x=1"));
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe("https://permissions.poc.nicholaswood.com.au/reports?x=1");
    const s = verifySession(readCookie(res.headers.get("set-cookie")), SECRET, NOW);
    expect(s).toMatchObject({ app: "permissions", uid: "uid-1", email: "member@example.com", role: "member" });
    expect(res.headers.get("set-cookie")).toContain("HttpOnly");
  });
  test("the same ticket cannot be used twice", async () => {
    const used = new Set<string>();
    const ticket = signHandoff(claims, hub.priv, NOW);
    expect((await receiver({ used })(get(ticket))).headers.get("set-cookie")).toContain("__session=");
    const second = await receiver({ used })(get(ticket));
    expect(second.headers.get("set-cookie")).toBeNull();
    expect(second.headers.get("location")).toBe("https://permissions.poc.nicholaswood.com.au/sign-in?hub=failed");
  });
  test("a bad, missing or wrong-app ticket gets no cookie and lands on this app\x27s own sign-in, never back at the hub", async () => {
    for (const t of [null, "nonsense", signHandoff({ ...claims, aud: "oss" }, hub.priv, NOW), signHandoff(claims, other.priv, NOW), signHandoff(claims, hub.priv, NOW - 600)]) {
      const res = await receiver()(get(t));
      expect(res.headers.get("set-cookie")).toBeNull();
      expect(res.headers.get("location")).toBe("https://permissions.poc.nicholaswood.com.au/sign-in?hub=failed");
    }
  });
  test("an off-site redirect is ignored", async () => {
    const res = await receiver()(get(signHandoff(claims, hub.priv, NOW), "https://evil.example/"));
    expect(res.headers.get("location")).toBe("https://permissions.poc.nicholaswood.com.au/");
  });
  test("after a hub key rotation the receiver refetches once and accepts the new key", async () => {
    let calls = 0;
    const key = async (force?: boolean) => (calls++, force ? hub.pub : other.pub);
    const res = await receiver({ key })(get(signHandoff(claims, hub.priv, NOW)));
    expect(res.headers.get("set-cookie")).toContain("__session=");
    expect(calls).toBe(2);
  });
  test("if the hub key cannot be fetched, sign-in fails closed", async () => {
    const res = await receiver({ key: async () => { throw new Error("down"); } })(get(signHandoff(claims, hub.priv, NOW)));
    expect(res.headers.get("set-cookie")).toBeNull();
  });
});

describe("hub key fetcher", () => {
  test("caches, and force refetches", async () => {
    let n = 0;
    const f = hubKeyFetcher("https://poc.nicholaswood.com.au/", 60_000, (async () => (n++, new Response(JSON.stringify({ publicKey: hub.pub })))) as unknown as typeof fetch);
    await f(); await f();
    expect(n).toBe(1);
    await f(true);
    expect(n).toBe(2);
  });
  test("rejects a malformed response", async () => {
    const f = hubKeyFetcher("https://poc.nicholaswood.com.au", 1, (async () => new Response(JSON.stringify({ publicKey: 42 }))) as unknown as typeof fetch);
    expect(f()).rejects.toThrow();
  });
});
`);' && cat packages/poc-auth/src/safe-redirect.ts | head -12 && bun test packages/poc-auth > /tmp/h.log 2>&1; grep -E '^ *[0-9]+ (pass|fail)' /tmp/h.log | tr '\n' ' '; grep -E "^\(fail\)" /tmp/h.log | cut -c1-170; (cd packages/poc-auth && bunx tsc --noEmit 2>&1 | head -5; echo "tsc $?")

