    store.users.get("member@example.com")!.pocs.oss = "admin";
    const t = verifyHandoff(loc(await h.launch(req("GET", "/launch/oss", "member@example.com"), "oss")).searchParams.get("ticket"), HANDOFF_PUB, "oss", NOW);
    expect(t!.role).toBe("admin");
  });
  test("no allocation: no ticket. Normal launch goes to the hub with a notice; silent goes back to the POC\x27s own sign-in", async () => {
    const { h, req, store } = setup();
    store.pocs.get("permissions")!.handoff = true;
    const normal = loc(await h.launch(req("GET", "/launch/permissions", "member@example.com"), "permissions"));
    expect(normal.href).toBe("https://poc.nicholaswood.com.au/?notice=noaccess");
    const silent = loc(await h.launch(req("GET", "/launch/permissions?silent=1&redirect=/x", "member@example.com"), "permissions"));
    expect(silent.origin + silent.pathname).toBe("https://permissions.poc.nicholaswood.com.au/sign-in");
    expect(silent.searchParams.get("hub")).toBe("noaccess");
    expect(silent.searchParams.get("ticket")).toBeNull();
  });
  test("signed out: normal launch asks for hub sign-in and comes back; silent returns to the POC\x27s individual sign-in", async () => {
    const { h, req, store } = setup();
    withHandoff(store);
    const normal = loc(await h.launch(req("GET", "/launch/oss?redirect=/a"), "oss"));
    expect(normal.origin + normal.pathname).toBe("https://poc.nicholaswood.com.au/sign-in");
    expect(normal.searchParams.get("redirect")).toBe("/launch/oss?redirect=%2Fa");
    const silent = loc(await h.launch(req("GET", "/launch/oss?silent=1"), "oss"));
    expect(silent.origin + silent.pathname).toBe("https://service-summary.poc.nicholaswood.com.au/sign-in");
    expect(silent.searchParams.get("hub")).toBe("none");
  });
  test("a POC that has not adopted handoff, or a hub with no key, is linked directly with no ticket", async () => {
    const a = setup();
    expect(loc(await a.h.launch(a.req("GET", "/launch/oss?redirect=/r", "member@example.com"), "oss")).href).toBe("https://service-summary.poc.nicholaswood.com.au/r");
    const b = setup("");
    withHandoff(b.store);
    expect(loc(await b.h.launch(b.req("GET", "/launch/oss", "member@example.com"), "oss")).href).toBe("https://service-summary.poc.nicholaswood.com.au/");
    expect((await b.h.handoffKey()).status).toBe(404);
  });
  test("unknown, malformed or pending POC ids never produce a ticket or an off-site redirect", async () => {
    const { h, req, store } = setup();
    store.pocs.set("soon", { id: "soon", name: "Soon", hostname: "soon.poc.nicholaswood.com.au", status: "pending", handoff: true });
    for (const id of ["ghost", "..%2f", "soon", "https://evil.example"]) {
      expect(loc(await h.launch(req("GET", "/launch/x", "nick@example.com"), id)).href).toBe("https://poc.nicholaswood.com.au/?notice=unknown");
    }
  });
  test("an off-site redirect parameter is dropped", async () => {
    const { h, req, store } = setup();
    withHandoff(store);
    const u = loc(await h.launch(req("GET", "/launch/oss?redirect=https://evil.example/", "member@example.com"), "oss"));
    expect(u.searchParams.get("redirect")).toBe("/");
  });
  test("the hub publishes the public half of the key", async () => {
    const { h } = setup();
    const res = await h.handoffKey();
    expect(res.status).toBe(200);
    expect((await res.json()).publicKey).toBe(HANDOFF_PUB);
  });
});
