# The hub is the front door for sign-in, so it gets the same three alerts as
# every POC (see modules/poc-app/monitoring.tf). Found missing on 24 Nov 2026:
# the uptime check above existed with nothing watching it.
resource "google_monitoring_alert_policy" "hub_uptime" {
  display_name          = "hub: health check failing"
  combiner              = "OR"
  notification_channels = [google_monitoring_notification_channel.email.name]
  conditions {
    display_name = "hub uptime"
    condition_threshold {
      filter          = "metric.type=\"monitoring.googleapis.com/uptime_check/check_passed\" AND resource.type=\"uptime_url\" AND metric.label.check_id=\"${google_monitoring_uptime_check_config.hub.uptime_check_id}\""
      comparison      = "COMPARISON_GT"
      threshold_value = 1
      duration        = "600s"
      aggregations {
        alignment_period     = "1200s"
        per_series_aligner   = "ALIGN_NEXT_OLDER"
        cross_series_reducer = "REDUCE_COUNT_FALSE"
        group_by_fields      = ["resource.label.host"]
      }
      trigger {
        count = 1
      }
    }
  }
}

resource "google_monitoring_alert_policy" "hub_errors_5xx" {
  display_name          = "hub: 5xx rate"
  combiner              = "OR"
  notification_channels = [google_monitoring_notification_channel.email.name]
  conditions {
    display_name = "hub 5xx responses"
    condition_threshold {
      filter          = "metric.type=\"run.googleapis.com/request_count\" AND resource.type=\"cloud_run_revision\" AND resource.label.service_name=\"${local.hub_service}\" AND metric.label.response_code_class=\"5xx\""
      comparison      = "COMPARISON_GT"
      threshold_value = 0.05
      duration        = "300s"
      aggregations {
        alignment_period     = "300s"
        per_series_aligner   = "ALIGN_RATE"
        cross_series_reducer = "REDUCE_SUM"
      }
    }
  }
}

resource "google_logging_metric" "hub_signin_failures" {
  name   = "hub-signin-failures"
  filter = "resource.type=\"cloud_run_revision\" AND resource.labels.service_name=\"${local.hub_service}\" AND jsonPayload.app_id=\"hub\" AND jsonPayload.event=\"auth.signin_failed\""
  metric_descriptor {
    metric_kind = "DELTA"
    value_type  = "INT64"
